import{_ as p,C as l,o as r,c as d,a2 as c,E as e,j as t,a as n}from"./chunks/framework.1lQk6gfR.js";const f=JSON.parse('{"title":"固定流程为技能重复使用","description":"把经过验证的流程固化为 Skill：明确触发条件、输入材料、执行步骤、工具规则、确认点与验收标准。","frontmatter":{"title":"固定流程为技能重复使用","description":"把经过验证的流程固化为 Skill：明确触发条件、输入材料、执行步骤、工具规则、确认点与验收标准。","prev":{"text":"明确交付要求与质量标准","link":"/30min/output"}},"headers":[],"relativePath":"30min/automate.md","filePath":"30min/automate.md","lastUpdated":1786896277000}'),u={name:"30min/automate.md"};function m(k,a,S,g,h,_){const s=l("AutoSkill"),o=l("AutoClock"),i=l("SkillStore");return r(),d("div",null,[a[0]||(a[0]=c(`<h1 id="固定流程为技能重复使用" tabindex="-1">固定流程为技能重复使用 <a class="header-anchor" href="#固定流程为技能重复使用" aria-label="Permalink to &quot;固定流程为技能重复使用&quot;">​</a></h1><p>当一项任务已经稳定做对，就不用下次再从头解释。把经过验证的任务约定和配合方式保存为技能（Skill），智能体才能在下一次拿到相似任务时稳定复用。</p><h2 id="技能不只是一句提示词" tabindex="-1">技能不只是一句提示词 <a class="header-anchor" href="#技能不只是一句提示词" aria-label="Permalink to &quot;技能不只是一句提示词&quot;">​</a></h2><p>这里的技能（Skill）不是一段孤立的提示词，也不是一个工具本身；它把一类任务的流程、所需资料、工具调用规则和验收标准固定下来，再由运行框架按这些规则组织执行。</p><p>从技术上看，一个 Skill 就是一个独立、规范命名的文件夹。以“工作讨论会行动安排”为例，常见构成如下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>meeting-action-plan/</span></span>
<span class="line"><span>├── SKILL.md              # 必需：用途、适用条件、执行步骤与验收标准</span></span>
<span class="line"><span>├── references/           # 可选：业务规则、字段说明、范例等参考资料</span></span>
<span class="line"><span>├── scripts/              # 可选：可重复执行的脚本或工具调用逻辑</span></span>
<span class="line"><span>└── templates/            # 可选：任务、邮件、表格或报告的输出模板</span></span></code></pre></div><p>智能体先根据名称和 <code>SKILL.md</code> 的简介发现合适的 Skill；需要时再读取其中的说明、资料、脚本或模板，不必把所有规则反复塞进每轮对话。</p><p>一项可复用的技能至少要说清五件事：</p><ol><li><strong>触发条件与目标</strong>：什么情况下启动，要完成哪一类任务。</li><li><strong>输入材料与范围</strong>：默认读取哪些资料，哪些资料不能使用或需要补充。</li><li><strong>执行流程与工具规则</strong>：先做什么、后做什么，需要调用哪些工具。</li><li><strong>确认点与例外处理</strong>：遇到哪些情况必须停下来请人判断。</li><li><strong>产出与验收标准</strong>：最终交付什么，以及怎样才算完成。</li></ol><h2 id="把跑通的协作流程转化为技能" tabindex="-1">把跑通的协作流程转化为技能 <a class="header-anchor" href="#把跑通的协作流程转化为技能" aria-label="Permalink to &quot;把跑通的协作流程转化为技能&quot;">​</a></h2><p>当你已经和智能体配合把一件事做顺了，不必从零编写。回看一次成功完成的任务，把“读取什么材料、按什么顺序做、哪里需要你确认、怎样检查结果”整理成技能说明，就能快速沉淀为可复用的 Skill。</p><p>以“把工作讨论会整理成行动安排”为例，技能可以规定：读取会议纪要和团队日历 → 提取行动项 → 核对时间冲突 → 生成任务草稿 → 按清单检查后返回。点播放，看核心内容怎样组合成一项可以重复使用的技能。</p>`,12)),e(s),a[1]||(a[1]=t("p",null,[n("如果不想从空白模板开始，可以调用 "),t("code",null,"skill-creator"),n("（也可理解为“创建技能”的元技能）。把已跑通的任务过程、使用的材料、工具调用、人工确认点和验收标准交给它，它会帮助你整理成一份可继续修改的 Skill 初稿；初稿仍需通过同类真实任务试跑，再补全规则。")],-1)),a[2]||(a[2]=t("p",null,"先用同类真实任务试跑，发现遗漏就补充规则；连续几次能按同一检查清单完成，再考虑将它用于更频繁的任务。写入、发送和提交等高影响动作仍可保留人工确认。",-1)),e(o),a[3]||(a[3]=t("h2",{id:"在智能体商店寻找合适的技能",tabindex:"-1"},[n("在智能体商店寻找合适的技能 "),t("a",{class:"header-anchor",href:"#在智能体商店寻找合适的技能","aria-label":'Permalink to "在智能体商店寻找合适的技能"'},"​")],-1)),a[4]||(a[4]=t("p",null,"不必每次都自己创建。面对常见任务，可以先到智能体商店按任务类型寻找现成 Skill；选中前重点核对它需要读取的资料、会调用的工具、默认的执行范围，以及最终交付和确认方式是否与你的工作一致。",-1)),e(i),a[5]||(a[5]=t("blockquote",null,[t("p",null,"无论是自己沉淀还是从商店选用，好技能都应该能在同类材料上稳定完成任务，清楚说明工具权限和人工确认点，并交付可检查的结果。")],-1))])}const x=p(u,[["render",m]]);export{f as __pageData,x as default};
